        if pending != nil || !held.isEmpty { adsOn = adState().eligible }
        if !adsOn { scrubCampaign() }
        pending?.commit()
        pending = nil
        store = disk
        if !held.isEmpty {
            bind()
            let ctx = context()
            let strip = config.stripParams
            for payload in held { queue.add(ctx: ctx, payload: adsOn ? payload : Core.cleanedPayload(payload, strip: strip)) }
            trimQueue()
            held.removeAll()
        }
    }

    /// `analytics` dəyəri dəyişə biləcək hər yerdən sonra çağırılır (razılıq artıq məlumdur).
    private func applyConsent(was: Bool) {
        undecided = false
        if !analytics {
            forget()
            return
        }
        // Razılıq geri alınıb yenidən verilibsə köhnə anonim ID ilə əlaqə qalmamalıdır.
        if !was { anonId = env.uuid() }
        settle()
        store.put(Keys.anon, anonId)
        if !ads {
            scrubCampaign()
            scrubQueue()
        }
        // Razılıq SDK başlayandan sonra verilibsə AppInstall / AppUpdate indi qiymətləndirilir (yenə bir dəfə).
        lifecycleVersionEvents()
    }

    /// İlk açılışda AppInstall, versiya dəyişəndən sonrakı ilk açılışda AppUpdate.
    private func lifecycleVersionEvents() {
        if !started || !analytics || dormant() { return }
        guard let app = env.deviceContext()["app"] as? [String: Any] else { return }
        let version = app["version"] as? String ?? ""
        let build = app["build"] as? String ?? ""
        let current = version + "|" + build
        let previous = store.get(Keys.appVersion)
        if previous == current { return }
        store.put(Keys.appVersion, current)
        guard autoEvents, config.auto("lifecycle") else { return }
        if let previous = previous {
            let parts = previous.split(separator: "|", maxSplits: 1, omittingEmptySubsequences: false).map(String.init)
            track("AppUpdate", props: ["previous_version": parts.first ?? "", "previous_build": parts.count > 1 ? parts[1] : ""], eventId: nil, origin: Core.originAuto)
        } else {
            track("AppInstall", props: nil, eventId: nil, origin: Core.originAuto)
        }
    }

