        guard let name = name, Util.isValidName(name) else {
            log("invalid event name")
            return
        }
        if config.blockedEvents.contains(name) || sampledOut() { return }
        var event = base(type: "track", origin: origin, at: at)
        event["name"] = name
        if let eventId = eventId {
            if Util.isValidId(eventId) {
                event["id"] = eventId
            } else {
                log("invalid eventId, a generated id is used instead")
            }
        }
        // Mətn dəyəri ünvandırsa ünvan kimi təmizlənir: konfiqin `strip_params` siyahısı ilə; klik ID-ləri yalnız toplu
        // reklama yararlı olanda (reklam razılığı və izləmə icazəsi var, bax `adState`) qalır.
        let adsOn = adState().eligible
        if let cleaned = Util.cleanObject(props, log: log, extra: config.stripParams, ads: adsOn) { event["props"] = cleaned }
        enqueue(event)
    }

