        guard started, analytics, !dormant() else { return }
        // E-poçt ünvanına və ya telefon nömrəsinə oxşayan istifadəçi ID-si açıq göndərilmir və saxlanmır: yerinə
        // normallaşdırılmış dəyərin SHA-256-sı işlədilir (veb tracker və Android ilə eyni qayda, bax `Util.userId`).
        guard let user = Util.userId(id) else {
            log("invalid user id")
            return
        }
        if user != Util.text(id ?? "") { log("user id looks like an e-mail address or a phone number, its sha256 is sent instead") }
        userId = user
        store.put(Keys.user, user)
        if sampledOut() { return }
        var event = base(type: "identify", origin: Core.originCode, at: at)
        event["user_id"] = user
        // E-poçt və telefon cihazı yalnız hash şəklində tərk edir. Açar adı dəqiq `email` / `phone` olmaya bilər
        // (`Email`, `user_email`, `msisdn`): belə açarın açıq dəyəri onsuz da atılır, hash isə itməməlidir.
        // Ünvan dəyərlərindəki klik ID-ləri yalnız toplu reklama yararlı olanda qalır (bax `adState`).
        let adsOn = adState().eligible
        if let cleaned = Util.cleanTraits(traits, log: log, extra: config.stripParams, ads: adsOn) { event["traits"] = cleaned }
        enqueue(event)
    }

    func screen(_ name: String?, props: [String: Any?]?, origin: String = Core.originCode, at: Int64? = nil) {
        // Ekran adında e-poçta və telefon nömrəsinə bənzər hissələr gizlədilir (veb tracker-dəki səhifə başlığı kimi).
        // Ad ünvan şəklindədirsə ünvan kimi təmizlənir (konfiqin `strip_params` siyahısı və reklam uyğunluğu ilə).
        let given = Util.text(name ?? "", limit: Core.maxScreenInputLength)
        let cleaned = Util.text(Util.label(given, extra: config.stripParams, ads: adState().eligible), limit: Core.maxScreenNameLength)
        if cleaned.isEmpty { return }
        screenName = cleaned
        if origin == Core.originAuto, !autoEvents || !config.auto("screens") { return }
        track("ScreenView", props: props, eventId: nil, origin: origin, at: at)
    }

    /// İstifadəçinin seçimi əvvəlcə diskə yazılır, sonra yaddaşda qüvvəyə minir. Yazı alınmasa da seçim yaddaşda
    /// tətbiq olunur və yazı sonra təkrarlanır: disk xətası köhnə razılığı geri qaytara bilməz.
    func setConsent(analytics newAnalytics: Bool?, ads newAds: Bool?) {
        guard started else { return }
        let was = analytics
        let value = ((newAnalytics ?? analytics) ? "1" : "0") + ((newAds ?? ads) ? "1" : "0")
        disk.put(Keys.consent, value)
        if disk.unsaved { log("consent could not be saved, it stays in effect in memory and the write is retried") }
        userConsent = value
        consentLost = false
        // Yeni açıq seçim `initialize`-dəki dəyərdən və təkrar `initialize`-in məhdudiyyətlərindən sonra gəlib.
        initConsent = nil
        restrictAnalytics = false
        restrictAds = false
        resolve()
        applyConsent(was: was)
        // Analitika rədd ediləndə konfiq soruşulmurdu: razılıq veriləndə indi alınır.
        refreshConfig()
    }

    /// Təkrar `initialize` çağırışının seçimləri: yalnız sərtləşdirən hissəsi tətbiq olunur (`consent`-in `false` olan
    /// məqsədləri və `collectAdvertisingId = false`); heç nə yumşaldılmır.
    func restrict(consent: SmartBeeConsent?, collectAdvertisingId: Bool) {
        guard started else { return }
        let was = analytics
        if !collectAdvertisingId { collectAdId = false }
        if let consent = consent {
            if !consent.analytics { restrictAnalytics = true }
            if !consent.ads { restrictAds = true }
        }
        resolve()
        if !analytics, was {
            applyConsent(was: was)
        } else if !ads {
            scrubCampaign()
            scrubQueue()
        }
    }

    /// `newId`: yeni anonim ID (açıq çağırışda yaradılır ki, `SmartBee.anonymousId` dərhal onu qaytarsın).
    func reset(newId: String? = nil) {
        guard started else { return }
        flush(force: true)
        userId = nil
        screenName = nil
        lastLink = nil
        for name in [Keys.user, Keys.session, Keys.seq, Keys.campaign, Keys.campaignAt] { store.remove(name) }
        if let given = newId, Util.isValidId(given) {
            anonId = given
        } else {
            anonId = env.uuid()
        }
        if analytics { store.put(Keys.anon, anonId) }
    }

    /// Tətbiq ön plana keçdi. `tracked = false`: həyat dövrü izlənmir və arxa fon xəbəri gəlməyəcək,
    /// ona görə sessiya əvvəlki kimi son fəaliyyətdən keçən vaxtla bitir. `at`: keçidin anı.
    /// AppOpen konfiq sorğusundan əvvəl yazılır: yavaş şəbəkə onu gecikdirmir.
    func onForeground(tracked: Bool = true, at: Int64? = nil) {
        guard started else { return }
        if tracked, !foreground {
            // Sessiya tətbiq arxa fonda `session_timeout_s`-dən çox qaldıqda yenilənir (PROTOCOL.md 6).
            let saved = savedSession()
            if !saved.id.isEmpty {
                let away = env.now().subtractingReportingOverflow(saved.last)
                if away.overflow || away.partialValue > config.sessionTimeoutMs { store.remove(Keys.session) }
            }
            foreground = true
        }
        if autoEvents, config.auto("lifecycle") {
            track("AppOpen", props: nil, eventId: nil, origin: Core.originAuto, at: at)
        }
        refreshConfig()
        flush()
    }

    /// Tətbiq arxa fona keçdi: növbə dərhal göndərilir.
    func onBackground() {
        guard started else { return }
        foreground = false
        let saved = savedSession()
        if !saved.id.isEmpty { store.put(Keys.session, "\(saved.id)|\(env.now())") }
        flush(force: true)
    }

    func onDeepLink(_ url: String?, at: Int64? = nil) {
        guard started, let url = url, !url.isEmpty else { return }
        // Uzunluq hər hansı emaldan (təhlil, təmizləmə) əvvəl yoxlanır.
        if url.utf16.count > Util.maxUrlLength {
            log("deep link is longer than \(Util.maxUrlLength) characters, ignored")
            return
        }
        guard analytics, !dormant() else { return }
        guard Util.isLink(url) else {
            log("not a deep link, ignored")
            return
        }
        // Eyni keçid tətbiqə bir neçə sistem metodundan ötürülə bilər: qısa müddətdə təkrarı bir dəfə sayılır.
        let now = env.now()
        if let last = lastLink, last == url, now >= lastLinkAt, now - lastLinkAt < Core.linkRepeatMs { return }
        lastLink = url
        lastLinkAt = now
        // Reklama yararlı deyilsə (razılıq və ya izləmə icazəsi yoxdur) klik ID-ləri nə diskə yazılır, nə göndərilir.
        // Razılıq hələ məlum deyilsə `store` yaddaşdakı qatdır və event yaddaşda gözləyir: diskə nəyin düşəcəyini
        // `settle` həll edir.
        let adsOn = adState().eligible
        if let campaign = Util.campaignOf(url, withClickIds: adsOn, extraStrip: config.stripParams), let json = Util.jsonString(campaign) {
            store.put(Keys.campaign, json)
            store.put(Keys.campaignAt, String(now))
        }
        if autoEvents, config.auto("deeplinks") {
            // Reklama yararlı deyilsə klik ID-ləri ünvanda da qalmır (kontekstin `campaign` hissəsi ilə eyni qayda).
            let shown = Util.cleanUrl(url, extraStrip: config.stripParams, ads: adsOn)
            track("DeepLinkOpen", props: ["url": shown], eventId: nil, origin: Core.originAuto, at: at)
        }
    }

    // MARK: - Eventin qurulması

    private func sampledOut() -> Bool {
        return config.sample < 1.0 && Util.fraction(anonId) >= config.sample
    }

    /// Saxlanmış sessiya: ID və son fəaliyyət vaxtı. Yoxdursa və ya pozulubsa ID boşdur.
    private func savedSession() -> (id: String, last: Int64) {
        let raw = store.get(Keys.session) ?? ""
        guard let sep = raw.lastIndex(of: "|"), sep != raw.startIndex else { return (id: "", last: 0) }
        let id = String(raw[raw.startIndex..<sep])
        let last = Int64(String(raw[raw.index(after: sep)...])) ?? 0
        if Util.isValidId(id), last > 0 { return (id: id, last: last) }
        return (id: "", last: 0)
    }

    /// `now` eventin vaxtıdır, `clock` cihazın indiki vaxtı. Diskdən oxunan dəyər pozulmuş ola bilər,
    /// ona görə fərq daşmaya qarşı yoxlanılır.
    private func session(_ now: Int64, clock: Int64) -> String {
        let saved = savedSession()
        var id = saved.id
        let last = saved.last
        let diff = now.subtractingReportingOverflow(last)
        var elapsed = diff.partialValue
        var stamp = now
        // Çağırış anında qeyd olunmuş vaxt növbədə gözləyərkən sessiyanın son vaxtından geri qala bilər;
        // cihazın saatı geri çəkilməyibsə bu, yeni sessiya demək deyil.
        if !diff.overflow, elapsed < 0, last <= clock {
            elapsed = 0
            stamp = last
        }
        // Ön planda sessiya bitmir; ön plan vəziyyəti məlum deyilsə son fəaliyyətdən keçən vaxta baxılır.
        let expired = !foreground && elapsed > config.sessionTimeoutMs
        let fresh = id.isEmpty || diff.overflow || expired || elapsed < -60_000
        if fresh { id = env.uuid() }
        store.put(Keys.session, "\(id)|\(stamp)")
        if fresh, !inSessionStart, autoEvents {
            inSessionStart = true
            track("SessionStart", props: nil, eventId: nil, origin: Core.originAuto, at: now)
            inSessionStart = false
        }
        return id
    }

    private func nextSeq() -> Int64 {
        var next: Int64 = 0
        if let saved = store.get(Keys.seq).flatMap({ Int64($0) }), saved >= 0, saved < Core.maxSeq {
            next = saved + 1
        }
        store.put(Keys.seq, String(next))
        return next
    }

    private func base(type: String, origin: String, at: Int64?) -> [String: Any] {
        let clock = env.now()
        let now = at ?? clock
        let sessionId = session(now, clock: clock)
        var event: [String: Any] = [
            "id": env.uuid(),
            "type": type,
            "ts": Util.iso(now),
            "anon_id": anonId,
            "session_id": sessionId,
            "seq": nextSeq(),
        ]
        if let userId = userId { event["user_id"] = userId }
        if origin != Core.originCode { event["origin"] = origin }
        if let screenName = screenName { event["screen"] = ["name": screenName] }
        return event
    }

    /// Reklam məlumatının indiki vəziyyəti. Toplu reklama yalnız bunların hamısı ödənəndə yararlıdır:
    /// reklam razılığı var (və çağıran axında geri alınmayıb) və sistem izləməyə icazə verir. iOS / tvOS 14+-da bu,
    /// App Tracking Transparency vəziyyətinin `authorized` olması deməkdir; icazə verilməyibsə, soruşulmayıbsa və ya
    /// vəziyyət oxunmursa toplu yararsızdır. ATT olmayan sistemdə (iOS 13) razılıq kifayətdir.
    ///
    /// `collectAdvertisingId = false`: nə IDFV, nə IDFA, nə də ATT vəziyyəti oxunur; icazə məlum olmadığından
    /// ATT tələb olunan sistemdə toplu reklama yararsız sayılır.
    /// Vəziyyət hər çağırışda sistemdən yenidən oxunur, ona görə köhnə icazə ilə alınmış dəyər saxlanmır.
    private func adState() -> AdState {
        guard ads, !gate.adsDenied else { return AdState(eligible: false, status: nil, idfa: nil) }
        guard collectAdId else { return AdState(eligible: !env.attRequired(), status: nil, idfa: nil) }
        let info = env.advertising(includeId: true)
        var status: String?
        var authorized = !env.attRequired()
        if let value = info.status {
            authorized = value == Core.attAuthorized
            if Core.attStatuses.contains(value) { status = value }
        }
        return AdState(eligible: authorized, status: status, idfa: authorized ? Util.advertisingId(info.idfa) : nil)
    }

    /// Kontekstin `ids` hissəsi. Cihaz identifikatorları (IDFV, IDFA) yalnız toplu reklama yararlı olanda və
    /// `collectAdvertisingId` açıq olanda göndərilir. `att` (ATT vəziyyəti) reklam razılığı olanda və oxunanda əlavə
    /// olunur: icazə yoxdursa `ids` yalnız ondan ibarətdir.
    private func identifiers(_ base: Any?, _ state: AdState) -> [String: Any]? {
        var ids: [String: Any] = [:]
        if state.eligible, collectAdId {
            ids = base as? [String: Any] ?? [:]
            // Bu iki sahə yalnız aşağıdakı qayda ilə yazılır, cihaz kontekstindən gələn dəyər nəzərə alınmır.
            ids["idfa"] = nil
            ids["att"] = nil
            if let idfa = state.idfa { ids["idfa"] = idfa }
        }
        if let status = state.status { ids["att"] = status }
        return ids.isEmpty ? nil : ids
    }

    private func dropCampaign() {
        store.remove(Keys.campaign)
        store.remove(Keys.campaignAt)
    }

    /// Saxlanmış kampaniya; `campaignTtlMs`-dən köhnədirsə və ya pozulubsa silinir.
    private func campaign(_ state: AdState) -> [String: Any]? {
        guard let saved = store.get(Keys.campaign) else { return nil }
        let storedAt = store.get(Keys.campaignAt).flatMap { Int64($0) } ?? 0
        let age = env.now().subtractingReportingOverflow(storedAt)
        if storedAt <= 0 || age.overflow || age.partialValue > Core.campaignTtlMs {
            dropCampaign()
            return nil
        }
        guard let parsed = Util.parseObject(saved) else {
            dropCampaign()
            return nil
        }
        var out: [String: Any] = [:]
        for (name, value) in parsed {
            guard let string = value as? String else { continue }
            // Saxlanmış dəyər göndərilməzdən əvvəl yenə təmizlənir (veb tracker-in `pickCampaign` funksiyası kimi).
            let cleaned = Util.campaignValue(string, extraStrip: config.stripParams, ads: state.eligible, utm: Util.isUtmName(name))
            if !cleaned.isEmpty { out[name] = cleaned }
        }
        // Reklama yararlı deyilsə klik ID-ləri göndərilmir.
        if !state.eligible { for id in Util.clickIds { out[id] = nil } }
        return out.isEmpty ? nil : out
    }

    /// Reklam razılığı yoxdur: saxlanmış kampaniyadan klik ID-ləri diskdən də silinir.
    private func scrubCampaign() {
        guard let saved = store.get(Keys.campaign) else { return }
        guard var parsed = Util.parseObject(saved) else {
            dropCampaign()
            return
        }
        var changed = false
        for id in Util.clickIds where parsed[id] != nil {
            parsed[id] = nil
            changed = true
        }
        if !changed { return }
        if parsed.isEmpty {
            dropCampaign()
        } else if let json = Util.jsonString(parsed) {
            store.put(Keys.campaign, json)
        } else {
            dropCampaign()
        }
    }

    private func context() -> String {
        var ctx = Util.clampContext(env.deviceContext())
        let state = adState()
        if state.eligible { adRows = true }
        ctx["platform"] = "ios"
        // `consent.ads` serverə toplunun reklam platformalarına ötürülə biləcəyini deyir: razılıq olsa belə
        // izləmə icazəsi (ATT) yoxdursa false göndərilir.
        ctx["consent"] = ["analytics": analytics, "ads": state.eligible]
        if let ids = identifiers(ctx["ids"], state) {
            ctx["ids"] = ids
        } else {
            ctx["ids"] = nil
        }
        if let stored = campaign(state) { ctx["campaign"] = stored }
        var json = Util.jsonString(ctx)
        // Kampaniya xarici keçiddən gəlir: konteksti həddən böyük edirsə atılır, yoxsa sonrakı bütün toplular rədd olunardı.
        if let text = json, text.utf8.count > Core.maxCtxBytes, ctx["campaign"] != nil {
            ctx["campaign"] = nil
            dropCampaign()
            json = Util.jsonString(ctx)
        }
        return json ?? "{\"platform\":\"ios\"}"
    }

    private func enqueue(_ event: [String: Any]) {
        guard let payload = Util.jsonString(event) else {
            log("event is not serializable, dropped")
            return
        }
        if payload.utf8.count > Core.maxEventBytes {
            log("event too large, dropped")
            return
        }
        if undecided {
            held.append(payload)
            if held.count > Core.maxHeld {
                held.removeFirst()
                log("more than \(Core.maxHeld) events are waiting for the consent decision, dropped the oldest")
            }
            return
        }
        bind()
        queue.add(ctx: context(), payload: payload)
        trimQueue()
        if queue.count >= config.maxBatch { flush() }
    }

    // MARK: - Göndərmə

    /// `until` hələ gəlməyibsə true. Saat geri çəkilibsə (hədd ağlasığmaz uzaqdadırsa) köhnə hədd sonsuz gözlətmir.
    private func waiting(_ until: Int64, _ now: Int64) -> Bool {
        return now < until && until &- now <= Core.maxWaitMs
    }

    private func backoff(_ count: Int) -> Int64 {
        let shift = Int64(min(max(count - 1, 0), 20))
        let base = min(Core.backoffBaseMs << shift, Core.backoffMaxMs)
        return Int64(Double(base) * (0.8 + env.random() * 0.4))
    }

    /// Növbəni toplu-toplu göndərir. Uğursuzluqdan sonra artan fasilə gözlənilir;
    /// `force` bu fasiləni nəzərə almır (arxa fona keçid, əl ilə flush), serverin `Retry-After` tələbini isə almır.
    func flush(force: Bool = false) {
        guard started else { return }
        if disk.unsaved { disk.retrySave() }
        let now = env.now()
        if undecided || keyOff {
            // Razılıq məlum deyil və ya açar söndürülüb: əvvəlcə konfiq alınmalıdır (öz fasilələri ilə).
            refreshConfig()
            if undecided || keyOff { return }
        }
        if !analytics || !config.enabled {
            clearQueue()
            return
        }
        if gate.analyticsDenied { return }
        if waiting(holdUntil, now) { return }
        if !force, waiting(nextAttemptAt, now) { return }
        var limit = config.maxBatch
        var rounds = 0
        var stuck = Stuck.parse(disk.get(Keys.stuck))
        while rounds < Core.maxBatchesPerFlush {
            rounds += 1
            // Razılıq bu arada (başqa axında) geri alına bilər: hər sorğudan əvvəl yoxlanır.
            if gate.analyticsDenied { return }
            // Reklam vəziyyəti (razılıq və izləmə icazəsi) hər toplu üçün yenidən oxunur: reklam razılığı göndəriş
            // ortasında geri alınıbsa qalan toplular reklam məlumatsız gedir.
            let state = adState()
            var rewritten: [String: String] = [:]
            // Reklama yararlı deyilsə reklam məlumatı növbədəki sətirlərdən də (diskdən) silinir.
            if !state.eligible { scrubQueue() }
            // Təcrid rejimi (bax `Stuck`): sətirlər bir-bir göndərilir.
            var take = limit
            if let known = stuck, known.solo > 0 { take = 1 }
            let rows = queue.peek(take)
            guard let first = rows.first else {
                if stuck != nil { disk.remove(Keys.stuck) }
                return
            }
            // Eyni kontekstli ardıcıl eventlər bir topluya düşür (PROTOCOL.md 5.3).
            // Müqayisə göndərilən kontekstlə aparılır: reklam razılığı geri alınıbsa yalnız reklam sahələri ilə
            // fərqlənən sətirlər eyni topluya düşür.
            let ctx = outgoing(first.ctx, cache: &rewritten, state: state)
            var batch: [QueuedEvent] = []
            var bytes = ctx.utf8.count + 256
            for row in rows {
                if outgoing(row.ctx, cache: &rewritten, state: state) != ctx { break }
                if !batch.isEmpty, bytes + row.payload.utf8.count > Core.maxBodyBytes { break }
                batch.append(row)
                bytes += row.payload.utf8.count + 1
            }
            let built = body(ctx: ctx, batch: batch)
            if !built.bad.isEmpty {
                // Pozulmuş sətirlər: təkrar cəhdin mənası yoxdur. Yalnız onlar silinir, toplunun qalanı göndərilir.
                log("dropped \(built.bad.count) corrupt queue rows")
                queue.remove(built.bad)
            }
            guard let json = built.json else { continue }
            // Toplu qurularkən razılıq geri alına bilər: sorğudan dərhal əvvəl yenidən yoxlanır.
            if gate.analyticsDenied { return }
            // Reklam razılığı toplu qurulandan sonra geri alınıbsa bu gövdə göndərilmir, yenisi qurulur.
            if state.eligible, gate.adsDenied { continue }
            let result = transport.post(url: endpoint + "/v1/e", json: json)
            switch result.verdict(events: built.sent.count) {
            case .retry:
                failures += 1
                let wait: Int64
                if let retryAfter = result.retryAfterSec {
                    // Serverin tələbi 0–20% müsbət kənarlaşma ilə: bütün cihazlar eyni saniyədə qayıtmasın.
                    wait = Int64(Double(min(max(retryAfter, 1), 3600) * 1000) * (1.0 + env.random() * 0.2))
                    holdUntil = now &+ wait
                } else {
                    wait = backoff(failures)
                }
                nextAttemptAt = now &+ wait
                log("send failed (\(result.status)), retry in \(wait)ms")
                if !Stuck.counts(result.status) {
                    // 5xx / şəbəkə xətası / 408 / 429: toplunun özü ilə bağlı deyil, ardıcıl 4xx sayğacı sıfırlanır.
                    if let known = stuck, known.solo == 0 { disk.remove(Keys.stuck) }
                    return
                }
                // Tanınan kodu olmayan 4xx (WAF, proksi): eyni toplu ardıcıl rədd olunursa növbə əbədi bağlanmamalıdır.
                guard let head = batch.first else { return }
                let headKey = String(Util.sha256(head.payload).prefix(16))
                var solo = 0
                if let saved = stuck { solo = saved.solo }
                var known = Stuck(key: headKey, fails: 0, since: now, solo: solo)
                if let saved = stuck, saved.key == headKey, now >= saved.since { known = saved }
                let fails = known.fails + 1
                if solo == 0, fails >= Core.stuckBatchTries {
                    // Toplu təcrid olunur: onun sətirləri bir-bir göndərilir (413-dəki bölmə yolu kimi).
                    let isolated = Stuck(key: headKey, fails: 0, since: known.since, solo: built.sent.count)
                    stuck = isolated
                    disk.put(Keys.stuck, isolated.text)
                    log("the same batch was rejected \(fails) times with \(result.status) and no known error code: its \(built.sent.count) events are now sent one by one")
                    if built.sent.count > 1 { continue }
                    return
                }
                let age = now.subtractingReportingOverflow(known.since)
                let expired = age.overflow || age.partialValue >= Core.stuckRowMs
                if solo > 0, fails >= Core.stuckRowTries || expired {
                    // Tək event də rədd olunur: atılır, qalan sətirlər davam edir.
                    log("event rejected \(fails) times with \(result.status) and no known error code, dropped: " + Core.eventLabel(head.payload))
                    queue.remove(built.sent)
                    if solo > 1 {
                        let next = Stuck(key: "", fails: 0, since: now, solo: solo - 1)
                        stuck = next
                        disk.put(Keys.stuck, next.text)
                    } else {
                        stuck = nil
                        disk.remove(Keys.stuck)
                    }
                    failures = 0
                    nextAttemptAt = 0
                    continue
                }
                let updated = Stuck(key: headKey, fails: fails, since: known.since, solo: solo)
                stuck = updated
                disk.put(Keys.stuck, updated.text)
                return
            case .split:
                // Toplu server üçün böyükdür: hamısını atmaq əvəzinə yarısı ilə yenidən cəhd olunur.
                limit = max(1, built.sent.count / 2)
                log("batch too large (413), retrying with \(limit) events")
                continue
            case .keyOff:
                log("batch rejected (\(result.status) unknown_key), dropped \(built.sent.count) events")
                queue.remove(built.sent)
                keyDisabled(now)
                return
            case .drop:
                let code = result.error ?? ""
                log("batch rejected (\(result.status) \(code)), dropped \(built.sent.count) events")
            case .accepted:
                break
            }
            // Qəbul olundu və ya qəti rədd edildi: təkrar göndərilmir.
            failures = 0
            nextAttemptAt = 0
            holdUntil = 0
            queue.remove(built.sent)
            if let known = stuck {
                // Təcrid olunmuş toplunun növbəti sətri; hamısı bitibsə adi göndərişə qayıdılır.
                if known.solo > 1 {
                    let next = Stuck(key: "", fails: 0, since: now, solo: known.solo - 1)
                    stuck = next
                    disk.put(Keys.stuck, next.text)
                } else {
                    stuck = nil
                    disk.remove(Keys.stuck)
                }
            }
        }
    }

    /// Sazlama loqu üçün eventin qısa təsviri (ad və ya tip, ID).
    private static func eventLabel(_ payload: String) -> String {
        guard let event = Util.parseObject(payload) else { return "unreadable event" }
        var label = event["type"] as? String ?? ""
        if let name = event["name"] as? String { label = name }
        let id = event["id"] as? String ?? ""
        return label + " " + id
    }

    /// Növbədəki sətirin göndərilən konteksti. Kontekst event növbəyə düşəndə qurulur; toplu indi reklama yararlı
    /// deyilsə (reklam razılığı və ya izləmə icazəsi sonradan geri alınıb) sətir cihaz identifikatorlarsız (IDFA, IDFV),
    /// klik ID-lərsiz (UTM qalır) və `consent.ads = false` ilə gedir: server eventi reklam platformalarına yalnız
    /// `consent.ads` true olanda ötürür. Əks istiqamət yoxdur: yararsız yaranmış sətir sonradan da `ads: false` ilə
    /// gedir. Reklam məlumatı növbədəki sətirdən də silinir (bax `scrubQueue`); buradakı təmizləmə ikinci müdafiə
    /// xəttidir. `cache` bir toplu daxilində eyni konteksti təkrar çevirməmək üçündür.
    private func outgoing(_ ctx: String, cache: inout [String: String], state: AdState) -> String {
        if let known = cache[ctx] { return known }
        var out = ctx
        if state.eligible {
            out = withoutStaleIds(ctx, state)
        } else if let object = Util.parseObject(ctx) {
            // Pozulmuş sətir olduğu kimi qalır: `body` də onu oxuya bilməyəcək və sətir növbədən silinəcək.
            out = Util.jsonString(withoutAds(object, status: state.status)) ?? "{\"platform\":\"ios\"}"
        }
        cache[ctx] = out
        return out
    }

    /// Kontekstdən reklam məlumatını çıxarır: cihaz identifikatorları (IDFA, IDFV) və klik ID-ləri silinir (UTM qalır),
    /// `consent.ads` false olur. `status` verilibsə `ids` yalnız ATT vəziyyətindən ibarət qalır.
    private func withoutAds(_ context: [String: Any], status: String?) -> [String: Any] {
        var object = context
        if let status = status {
            object["ids"] = ["att": status]
        } else {
            object["ids"] = nil
        }
        var consent: [String: Any] = object["consent"] as? [String: Any] ?? ["analytics": analytics]
        consent["ads"] = false
        object["consent"] = consent
        if var campaign = object["campaign"] as? [String: Any] {
            for id in Util.clickIds { campaign[id] = nil }
            if campaign.isEmpty {
                object["campaign"] = nil
            } else {
                object["campaign"] = campaign
            }
        }
        return object
    }

    /// Kontekst reklam məlumatı daşıyır: `ids`, `consent.ads = true` və ya kampaniyada klik ID-si.
    private static func carriesAds(_ context: [String: Any]) -> Bool {
        if context["ids"] != nil { return true }
        let consent = context["consent"] as? [String: Any]
        if (consent?["ads"] as? Bool) != false { return true }
        if let campaign = context["campaign"] as? [String: Any] {
            for id in Util.clickIds where campaign[id] != nil { return true }
        }
        return false
    }

    /// Reklam razılığı və ya izləmə icazəsi yoxdur: reklam məlumatı növbədəki sətirlərdən (diskdən) silinir, göndəriş
    /// anını gözləmir. Kontekstdən cihaz identifikatorları və klik ID-ləri çıxarılır, `consent.ads` false olur;
    /// hər eventin `props` və `traits` hissəsi və ekran adı (`screen.name`) reklam razılığı olmadan yenidən təmizlənir
    /// (ünvan dəyərlərindən klik ID-ləri silinir; veb tracker-in `scrubEvents` funksiyası kimi). Əks istiqamət yoxdur:
    /// razılıq sonra yenidən verilsə də bu sətirlər `ads: false` ilə gedir. Növbəyə reklama yararlı sətir düşməyibsə
    /// növbəyə toxunulmur. Cari ekran adı da (sonrakı eventlərə yazılır) klik ID-siz qalır.
    private func scrubQueue() {
        if let name = screenName {
            let cleaned = Core.withoutClickIds(name: name, strip: config.stripParams)
            screenName = cleaned.isEmpty ? nil : cleaned
        }
        if !adRows { return }
        adRows = false
        if queue.count == 0 { return }
        let strip = config.stripParams
        var cache: [String: String] = [:]
        queue.update { row in
            var ctx = row.ctx
            if let known = cache[row.ctx] {
                ctx = known
            } else {
                if let object = Util.parseObject(row.ctx), Core.carriesAds(object),
                   let cleaned = Util.jsonString(self.withoutAds(object, status: nil)) {
                    ctx = cleaned
                }
                cache[row.ctx] = ctx
            }
            let payload = Core.cleanedPayload(row.payload, strip: strip)
            if ctx == row.ctx, payload == row.payload { return nil }
            return (ctx: ctx, payload: payload)
        }
    }

    /// Toplu reklama yararlıdır, amma sətirin daşıdığı identifikatorlar artıq göndərilə bilməz: `collectAdvertisingId`
    /// söndürülübsə `ids` bütöv çıxarılır; sistem IDFA-nı artıq vermirsə `ids.idfa` çıxarılır və `ids.att` indiki
    /// vəziyyəti göstərir. `ids`-siz kontekst olduğu kimi qaytarılır. Əks istiqamət yoxdur (sətirə identifikator
    /// sonradan əlavə olunmur).
    private func withoutStaleIds(_ ctx: String, _ state: AdState) -> String {
        guard ctx.contains("\"ids\""), var object = Util.parseObject(ctx), var ids = object["ids"] as? [String: Any] else {
            return ctx
        }
        if !collectAdId {
            object["ids"] = nil
            return Util.jsonString(object) ?? "{\"platform\":\"ios\"}"
        }
        if ids["idfa"] == nil || state.idfa != nil { return ctx }
        ids["idfa"] = nil
        ids["att"] = nil
        if let status = state.status { ids["att"] = status }
        if ids.isEmpty {
            object["ids"] = nil
        } else {
            object["ids"] = ids
        }
        return Util.jsonString(object) ?? "{\"platform\":\"ios\"}"
    }

    /// Eventin `props` və `traits` hissəsini və ekran adını (`screen.name`) reklam razılığı olmadan yenidən təmizləyir (veb
    /// tracker-in `scrubEvents` funksiyası kimi; vebdə ekran adının qarşılığı səhifə başlığıdır): ünvan dəyərlərindən
    /// (`DeepLinkOpen`-in `url`-i, tətbiqin öz verdiyi `link`, `landing`, ünvan şəklində ekran adı …) klik ID-ləri silinir,
    /// UTM və başqa parametrlər qalır. Artıq təmizlənmiş dəyər dəyişmir.
    private static func withoutClickIds(_ event: [String: Any], strip: Set<String>) -> [String: Any] {
        var out = event
        for field in Core.adFields {
            guard let value = event[field] as? [String: Any] else { continue }
            let input: [String: Any?] = value
            if let cleaned = Util.cleanObject(input, extra: strip, ads: false) {
                out[field] = cleaned
            } else {
                out[field] = nil
            }
        }
        if var screen = event["screen"] as? [String: Any], let name = screen["name"] as? String {
            let cleaned = Core.withoutClickIds(name: name, strip: strip)
            if cleaned != name {
                if cleaned.isEmpty {
                    out["screen"] = nil
                } else {
                    screen["name"] = cleaned
                    out["screen"] = screen
                }
            }
        }
        return out
    }

    /// Ekran adı reklam razılığı olmadan yenidən təmizlənir (bax `Util.label`); nəticə boş ola bilər.
    private static func withoutClickIds(name: String, strip: Set<String>) -> String {
        return Util.text(Util.label(name, extra: strip, ads: false), limit: Core.maxScreenNameLength)
    }

    /// Saxlanan (və ya saxlanacaq) eventin mətni üçün eyni təmizləmə. Dəyişiklik yoxdursa (və ya mətn oxunmursa) mətn
    /// olduğu kimi qayıdır.
    private static func cleanedPayload(_ payload: String, strip: Set<String>) -> String {
        guard payload.contains("\"props\"") || payload.contains("\"traits\"") || payload.contains("\"screen\""),
              let event = Util.parseObject(payload) else { return payload }
        let cleaned = Core.withoutClickIds(event, strip: strip)
        // `jsonString` açarları sıralayır: eyni məzmun eyni mətni verir.
        guard let before = Util.jsonString(event), let after = Util.jsonString(cleaned) else { return payload }
        return before == after ? payload : after
    }

    /// Qurulmuş toplu: `json` nil-dirsə göndəriləsi sətir yoxdur. `bad` pozulmuş sətirlər, `sent` topluya düşənlərdir.
    private struct Built {
        var json: String?
        var bad: [Int64]
        var sent: [Int64]
    }

    /// `ctx` artıq `outgoing`-dən keçmiş kontekstdir. Kontekstdə reklam razılığı yoxdursa (razılıqsız yaranmış və ya
    /// razılığı sonradan geri alınmış sətirlər) eventlərin `props` / `traits` ünvanları da klik ID-lərsiz gedir.
    /// Oxunmayan sətir ayrıca qeyd olunur: bir pozulmuş sətir bütün toplunu itirmir.
    private func body(ctx: String, batch: [QueuedEvent]) -> Built {
        guard let ctxObject = Util.parseObject(ctx) else {
            return Built(json: nil, bad: batch.map { $0.id }, sent: [])
        }
        let consent = ctxObject["consent"] as? [String: Any]
        let adsOn = (consent?["ads"] as? Bool) == true
        var events: [[String: Any]] = []
        var bad: [Int64] = []
        var sent: [Int64] = []
        for row in batch {
            guard let event = Util.parseObject(row.payload) else {
                bad.append(row.id)
                continue
            }
            events.append(adsOn ? event : Core.withoutClickIds(event, strip: config.stripParams))
            sent.append(row.id)
        }
        if sent.isEmpty { return Built(json: nil, bad: bad, sent: sent) }
        var sdk: [String: Any] = ["name": "ios", "version": pixelSdkVersion]
        // Yararsız örtük adı sxemi pozardı: göndərilmir.
        if let wrapper = Util.wrapperName(options.wrapper) {
            sdk["wrapper"] = wrapper
            if let wrapperVersion = Util.wrapperVersion(options.wrapperVersion) { sdk["wrapper_version"] = wrapperVersion }
        }
        let json = Util.jsonString([
            "v": 1,
            "key": key,
            "sent_at": Util.iso(env.now()),
            "sdk": sdk,
            "ctx": ctxObject,
            "events": events,
        ])
        guard let text = json else {
            // Toplu JSON-a çevrilmir: sətirlər pozulmuş sayılır.
            return Built(json: nil, bad: bad + sent, sent: [])
        }
        return Built(json: text, bad: bad, sent: sent)
    }

    // MARK: - Konfiq

    /// Server açarı tanımır (`unknown_key`): SDK dayanır, növbə və keşlənmiş konfiq qalır, sonra yenidən yoxlanır.
    private func keyDisabled(_ now: Int64) {
        keyOff = true
        keyOffAt = now
        held.removeAll()
        bind()
        disk.put(Keys.keyOffAt, String(now))
        log("the key is unknown or disabled (unknown_key): nothing is sent, the queue is kept, next check in \(Core.keyOffTtlMs / 60_000) min")
    }

    /// Konfiq köhnəlibsə serverdən yeniləyir.
    func refreshConfig(force: Bool = false) {
        guard started else { return }
        // Analitika açıq şəkildə rədd edilibsə şəbəkəyə çıxılmır (IP və açar serverə getmir).
        if gate.analyticsDenied || deniedByHost() { return }
        let now = env.now()
        if !force {
            if waiting(configRetryAt, now) { return }
            if keyOff {
                let off = now.subtractingReportingOverflow(keyOffAt)
                if !off.overflow, off.partialValue >= 0, off.partialValue < Core.keyOffTtlMs { return }
            } else {
                let fetchedAt = disk.get(Keys.configAt).flatMap { Int64($0) } ?? 0
                let age = now.subtractingReportingOverflow(fetchedAt)
                if haveConfig, fetchedAt != 0, !age.overflow, age.partialValue >= 0, age.partialValue < config.ttlMs { return }
            }
        }
        let result = transport.get(url: endpoint + "/v1/" + key + "/config", etag: haveConfig ? disk.get(Keys.configEtag) : nil)
        if result.status == 200, let body = result.body, let parsed = RemoteConfig.parse(body) {
            config = parsed
            bind()
            disk.put(Keys.config, body)
            if let etag = result.etag { disk.put(Keys.configEtag, etag) } else { disk.remove(Keys.configEtag) }
            disk.put(Keys.configAt, String(now))
            haveConfig = true
        } else if result.status == 304, haveConfig {
            disk.put(Keys.configAt, String(now))
        } else if result.status == 404, result.error == HttpResult.errorUnknownKey {
            // Yalnız serverin öz açıq cavabı açarı söndürür; başqa hər 404 / 4xx / 5xx müvəqqətidir (PROTOCOL.md 5.6).
            configFailures = 0
            configRetryAt = 0
            keyDisabled(now)
            return
        } else {
            // Cavab alınmadı: keşlənmiş konfiq qüvvədə qalır, növbəti cəhd artan fasilə ilə.
            configFailures += 1
            configRetryAt = now &+ backoff(configFailures)
            return
        }
        configFailures = 0
        configRetryAt = 0
        if keyOff {
            keyOff = false
            keyOffAt = 0
            disk.remove(Keys.keyOffAt)
        }
        noticeUpdate()
        // Yeni konfiqin `consent_default` dəyəri: tətbiq razılıq verməyibsə və istifadəçi seçim etməyibsə
        // dərhal qüvvəyə minir (Android ilə eyni qayda). Açıq bildirilmiş razılığa konfiq toxunmur.
        let was = analytics
        resolve()
        applyConsent(was: was)
        if !config.enabled { clearQueue() }
    }
}
